void StudioWindow::editLogicDocument(){
  if(bridge.busy())return;
  QDialog chooser(this);chooser.setObjectName("logicDocumentChooser");chooser.setWindowTitle(tr("시각 편집할 규칙 선택"));chooser.resize(900,600);auto box=new QVBoxLayout(&chooser);auto search=new QLineEdit;search->setPlaceholderText(tr("콘텐츠 이름 · 파일 · 규칙 경로 검색"));box->addWidget(search);auto list=new QListWidget;list->setObjectName("logicDocuments");box->addWidget(list);
  for(auto d:view.value("documents").toArray()){
    const auto doc=d.toObject();const auto data=doc.value("data");const auto file=doc.value("file").toString();const auto name=data.toObject().value("label").toString(data.toObject().value("name").toString(file));
    std::function<void(QJsonValue,QStringList)> scan=[&](QJsonValue v,QStringList path){QString kind;const auto o=v.toObject();auto op=o.value("op").toString();
      if(QStringList{"always","all","any","not","compare","flag","eventCompleted"}.contains(op))kind="condition";
      else if(o.contains("op")&&!o.contains("target")&&QStringList{"literal","time","read","add","subtract","multiply","clamp"}.contains(op))kind="number";
      else if(op=="read")kind="number";
      if(v.isArray()&&!path.empty()&&path.last().contains("effects",Qt::CaseInsensitive))kind="effects";
      if(!kind.isEmpty()){auto item=new QListWidgetItem(name+" · "+file+" /"+path.join('/'),list);item->setData(Qt::UserRole,doc);item->setData(Qt::UserRole+1,path);item->setData(Qt::UserRole+2,kind);return;}
      if(v.isObject())for(auto it=o.begin();it!=o.end();++it)scan(it.value(),path+QStringList{it.key()});else if(v.isArray()){int i=0;for(auto child:v.toArray())scan(child,path+QStringList{QString::number(i++)});}
    };scan(data,{});
  }
  connect(search,&QLineEdit::textChanged,&chooser,[list](QString text){for(int i=0;i<list->count();i++)list->item(i)->setHidden(!list->item(i)->text().contains(text,Qt::CaseInsensitive));});auto buttons=new QDialogButtonBox(QDialogButtonBox::Open|QDialogButtonBox::Cancel);box->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&chooser,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&chooser,&QDialog::reject);connect(list,&QListWidget::itemDoubleClicked,&chooser,&QDialog::accept);if(list->count())list->setCurrentRow(0);
  if(chooser.exec()!=QDialog::Accepted||!list->currentItem())return;auto item=list->currentItem();const auto doc=item->data(Qt::UserRole).toJsonObject();const auto path=item->data(Qt::UserRole+1).toStringList();LogicEditor editor(logicValueAt(doc.value("data"),path),item->data(Qt::UserRole+2).toString(),view,this);if(editor.exec()!=QDialog::Accepted)return;
  request("edit",{{"edit",QJsonObject{{"type","replace"},{"file",doc.value("file")},{"data",logicReplaceAt(doc.value("data"),path,editor.value())}}}});
}

