  for(bool isRule:{true,false}){auto row=isRule?rbuttons:fbuttons;for(auto pair:QList<QPair<QString,QString>>{{"Add",tr("추가")},{"Remove",tr("삭제")},{"Up",tr("위로")},{"Down",tr("아래로")}}){auto b=new QPushButton(pair.second);b->setObjectName(QString(isRule?"workflowRule":"workflowStep")+pair.first);row->addWidget(b);connect(b,&QPushButton::clicked,&dialog,[&,isRule,pair]{QJsonArray values;if(isRule)values=collectRules();else{collectFlow();values=actions[selectedOwner].toObject().value("flow").toArray();}int index=(isRule?rules:flows)->currentRow();if(pair.first=="Add"){QJsonObject v{{"id",nextId(values,isRule?"rule-":"step-")},{"condition",QJsonObject{{"op","always"}}},{"quantity",1}};if(isRule){v["name"]=tr("새 자동 규칙");v["trigger"]=QJsonObject{{"type","periodEnd"}};v["actionId"]=actions.first().toObject().value("id");}else v["thenActionId"]=actions.first().toObject().value("id");values.append(v);index=values.size()-1;}else if(index>=0){if(pair.first=="Remove")values.removeAt(index);else{int next=index+(pair.first=="Up"?-1:1);if(next>=0&&next<values.size()){auto v=values.takeAt(index);values.insert(next,v);index=next;}}}if(isRule)fillRules(values);else{auto a=actions[selectedOwner].toObject();a["flow"]=values;actions[selectedOwner]=a;fillFlow();}(isRule?rules:flows)->setCurrentCell(qMin(index,int(values.size())-1),0);});}}
